package com.aitutor.chat; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.*; public interface ConversationRepository extends JpaRepository<ChatConversation,Long>{List<ChatConversation> findByUserIdOrderByUpdatedAtDesc(Long userId); Optional<ChatConversation> findByIdAndUserId(Long id,Long userId); @Modifying(flushAutomatically = true, clearAutomatically = true) @Query("delete from ChatConversation c where c.user.id = :userId") void deleteByUserId(@Param("userId") Long userId);}
